/**
 * Endpoints sent as JSON even by a client using binary encoding.
 *
 * Each carries a bytes field that is not record data -- file contents, job
 * payloads, rendered images. JSON carries those as strings and Avro as raw
 * bytes, so encoding them as Avro would change the values a caller passes and
 * gets back.
 */
exports.JSON_ONLY_ENDPOINTS = new Set([
    '/create/job',
    '/create/proc',
    '/download/files',
    '/execute/proc',
    '/export/records/tofiles',
    '/filter/bystring',
    '/get/job',
    '/insert/records/frompayload',
    '/insert/symbol',
    '/show/proc',
    '/show/proc/status',
    '/upload/files',
    '/visualize/getfeatureinfo',
    '/visualize/image',
    '/visualize/image/chart',
    '/visualize/image/classbreak',
    '/visualize/image/contour',
    '/visualize/image/heatmap',
    '/visualize/image/labels',
    '/visualize/isochrone',
]);
/**
 * Endpoints whose records a binary client sends or receives as Avro.
 *
 * Inserted records are encoded with the table's type. Returned records are
 * decoded with the schema that arrives alongside them: a type schema for a
 * list of records, a dynamic schema for the column-major data of execute_sql
 * and the aggregates. Other endpoints keep their record data as JSON, inside
 * an Avro envelope.
 */
exports.BINARY_RECORD_ENDPOINTS = new Set([
    '/aggregate/groupby',
    '/aggregate/unique',
    '/aggregate/unpivot',
    '/execute/sql',
    '/get/records',
    '/get/records/bycolumn',
    '/insert/records',
    '/update/records',
]);
